"""
Statistical functions for data analysis.
"""

def mean(data):
    """Calculate the arithmetic mean of a list of numbers."""
    if not data:
        raise ValueError("Cannot calculate mean of empty list")
    return sum(data) / len(data)

def median(data):
    """Calculate the median of a list of numbers."""
    if not data:
        raise ValueError("Cannot calculate median of empty list")
    sorted_data = sorted(data)
    n = len(sorted_data)
    if n % 2 == 0:
        return (sorted_data[n//2 - 1] + sorted_data[n//2]) / 2
    else:
        return sorted_data[n//2]

def mode(data):
    """Calculate the mode(s) of a list of numbers."""
    if not data:
        raise ValueError("Cannot calculate mode of empty list")
    frequency = {}
    for item in data:
        frequency[item] = frequency.get(item, 0) + 1
    max_freq = max(frequency.values())
    modes = [k for k, v in frequency.items() if v == max_freq]
    return modes if len(modes) > 1 else modes[0]

def variance(data):
    """Calculate the sample variance of a list of numbers."""
    if not data:
        raise ValueError("Cannot calculate variance of empty list")
    if len(data) == 1:
        return 0
    data_mean = mean(data)
    return sum((x - data_mean) ** 2 for x in data) / (len(data) - 1)

def stdev(data):
    """Calculate the sample standard deviation of a list of numbers."""
    if not data:
        raise ValueError("Cannot calculate standard deviation of empty list")
    return variance(data) ** 0.5

